  ui_story_32170601_46_dialog_content = "Dan aku tahu mereka mati untuk melindungiku dari Eclipsite...",
  ui_story_32170601_47_dialog_content = "Tapi arwah mereka masih hidup di dalam Scarlet Letter ku! Itulah mengapa aku tidak pernah sendirian.",
