  ui_story_32170601_50_dialog_content = "Boo-hoo, kamu-kamu berbohong, Bu! Kamu bilang bahwa bug yang cantik akan muncul ketika bunga mulai mekar—",
  ui_story_32170601_51_dialog_content = "Kaktus-kaktus sedang mekar, tapi aku tidak melihat \"kupu-kupu\" di mana pun!",
  ui_story_32170601_52_dialog_content = "Aku yakin mereka bahkan tidak ada!",
  ui_story_32170601_53_dialog_content = "Oh sayang, aku takkan pernah berbohong padamu! Tapi kita tinggal di gurun, dan kupu-kupu adalah pemandangan yang jarang di sini.",
