  ui_story_32170601_56_dialog_content = "Lalu kita bisa melihat kupu-kupu bersama-sama, oke?",
  ui_story_32170601_57_dialog_content = "Ternyata ibuku tidak berbohong.",
  ui_story_32170601_58_dialog_content = "Setelah aku meninggalkan gurun, aku melihat berbagai jenis kupu-kupu...",
  ui_story_32170601_59_dialog_content = "Dan mereka semua sama cantiknya seperti yang dia deskripsikan.",
  ui_story_32170601_60_dialog_content = "Tapi meskipun dia berjanji untuk bertemu mereka bersamaku, ibuku sudah...",
  ui_story_32170601_61_dialog_content = "Pasolo...",
  ui_story_32170601_62_dialog_content = "Namun, semangat mereka selalu ada di sisiku, memberiku kekuatan.",
  ui_story_32170601_63_dialog_content = "Yang berarti pasti ada cara untuk berkomunikasi dengan mereka, bukan kamu pikir begitu?",
  ui_story_32170601_64_dialog_content = "Sebuah cara untuk berkomunikasi dengan orang yang sangat kita cintai yang telah meninggal...",
  ui_story_32170601_65_option_content = "Sejujurnya, saya tidak tahu.",
  ui_story_32170601_66_dialog_content = "Tapi tetap saja, tidak ada yang akan percaya pada sesuatu yang luar biasa seperti kupu-kupu kecuali mereka melihatnya sendiri.",
  ui_story_32170601_67_dialog_content = "Jadi siapa yang bisa mengatakan bahwa tidak ada cara untuk berbicara dengan orang-orang yang telah kita kehilangan? Mungkin kita hanya belum menemukannya?",
  ui_story_32170601_68_option_content = "Saya rasa belum ada yang menemukan cara.",
