  ui_story_32170601_77_dialog_content = "Sinsa, kamu bodoh besar! Kamu akan merobek uang bersama mereka!",
  ui_story_32170601_78_dialog_content = "Kamu tidak perlu berusaha keras seperti ini! Itu hanya amplop kertas, bukan Eclipsites!",
  ui_story_32170601_79_dialog_content = "Hahaha! Maaf Eve, saya mencium bau rediesel dari suatu tempat, dan itu membuat darah saya mendidih!",
  ui_story_32170601_80_dialog_content = "Rediesel? ... Tunggu, aku juga menciumnya!",
  ui_story_32170601_81_dialog_content = "Fiuh! Akhirnya, setelah berulang kali mencoba, saya berhasil membuat tumisan yang sempurna... Kenapa hidangan Longzhou begitu rumit?!",
  ui_story_32170601_82_dialog_content = "Berikutnya adalah delapan hidangan utama dan dua puluh empat lauk pauk.",
  ui_story_32170601_83_dialog_content = "... Apakah ada yang ingin membantu saya membuat makan malam liburan malam ini?",
  ui_story_32170601_84_dialog_content = "Vice, tolong! Apakah kamu... Apakah kamu pikir saya masih bisa menukar ini dengan Nightium? Hiks...",
  ui_story_32170601_85_dialog_content = "Jangan terlalu terpaku pada hal-hal kecil, Eve. Lihat saja Pasolo! Dia hampir berenang dalam kertas-kertas yang sobek dan itu sama sekali tidak mengganggunya!",
  ui_story_32170601_86_dialog_content = "Tapi itu semua hanya kertas bekas dari kerajinan tangan miliknya!",
  ui_story_32170601_87_dialog_content = "Wow, lihat kupu-kupu ini! Apakah kamu yang membuatnya sendiri, Pasolo? Kamu sangat berbakat...",
  ui_story_32170601_88_dialog_content = "Hah?! T-Tidak, ini benar-benar bukan apa-apa istimewa—",
  ui_story_32170601_89_dialog_content = "Ini dia, Pasolo! Sebuah amplop merah, hanya dari aku!",
  ui_story_32170601_90_dialog_content = "Aku juga membawa beberapa! ... Hanya saja, tolong hati-hati saat membukanya.",
  ui_story_32170601_91_dialog_content = "Aku akan menunggu sampai setelah makan malam untuk membagikan ini, tapi sepertinya semua orang sudah mulai... Ini, Pasolo!",
  ui_story_32170601_92_dialog_content = "K-Kalian...",
  ui_story_32170601_93_dialog_content = "Tunggu, apakah kalian semua menyiapkan amplop merah? Aku bukan satu-satunya yang tidak melakukannya, 'kan...?",
  ui_story_32170601_94_dialog_content = "Apa?! Tapi kamu kan Navigator! Bagaimana kamu bisa datang ke pesta tanpa bawa angpao?!",
  ui_story_32170601_95_dialog_content = "Ternyata tidak terpikir olehku...",
  ui_story_32170601_96_dialog_content = "Tidak apa-apa, PlayerName. Masih tidak terlambat untuk menyiapkan beberapa.",
  ui_story_32170601_97_dialog_content = "Baiklah, kalian berdua akan membantu saya memasak makan malam nanti! Ini dia hidangan tumisan yang baru saja saya buat!",
  ui_story_32170601_98_dialog_content = "Hah—K-Kamu tidak perlu menyeretku, Vice! Aku bisa berjalan ke sana sendiri.",
  ui_story_32170601_99_dialog_content = "Hahahaha! Hitung saya masuk jika kita memasak beberapa resep gaya Rediesel baru—!",
  ui_story_32170601_100_dialog_content = "Pasolo, kami serahkan urusan dekorasi padamu. Setelah kami selesai memasak makan malam, kita semua bisa duduk dan menikmati Festival Musim Semi tahun ini dengan baik!",
  ui_story_32170601_101_dialog_content = "A-Aku akan berusaha sebaik mungkin! Dan... Terima kasih untuk amplop merahnya, semua orang.",
  ui_story_32170601_102_dialog_content = "Hmm, apa ya yang tadi aku katakan?",
  ui_story_32170601_103_dialog_content = "Oh ya! Kamu tidak pernah sendirian, Pasolo.",
