  ui_story_32170601_105_dialog_content = "Aku masih memiliki Soroz, serta banyak teman yang bersedia berjuang di sisiku.",
  ui_story_32170601_106_dialog_content = "Dan meskipun sebagian besar dari mereka memiliki keluarga, mereka memilih untuk menghabiskan Festival Musim Semi tahun ini bersama saya dan teman-teman kami yang lain.",
  ui_story_32170601_107_dialog_content = "Untukmu, kamu adalah salah satu alasan mereka di sini sekarang.",
  ui_story_32170601_108_dialog_content = "Benarkah? Apakah semua orang... benar-benar bersedia bersamaku?",
  ui_story_32170601_109_dialog_content = "Tentu saja kami adalah. Kamu telah menjadi teman baik bagi kita semua untuk waktu yang lama sekarang.",
  ui_story_32170601_110_dialog_content = "Jadi, tolong tetap bersama kami saat kami terus menjalani petualangan hidup bersama.",
  ui_story_32170601_111_dialog_content = "Orang tuamu ingin menunjukkan kepadamu dunia dan semua keindahannya, jadi ayo kita lihat semuanya bersama. Oke?",
  ui_story_32170601_112_dialog_content = "PlayerName…",
  ui_story_32170601_113_dialog_content = "Aku... Aku berjanji jika kau pernah membutuhkan kekuatanku, aku akan selalu ada untukmu.",
  ui_story_32170601_114_dialog_content = "Tidak peduli kemana masa depan membawa kita, aku akan selalu berdiri di sisimu.",
  ui_story_32170601_115_dialog_content = "... J-Juga, aku tahu ini agak berlebihan, tapi bisakah kau... berjanji padaku sesuatu?",
  ui_story_32170601_116_dialog_content = "Tentu! Utarakan pikiranmu.",
  ui_story_32170601_117_dialog_content = "Sampai orang tua saya kembali berada di sisiku... Maukah kamu menjadi keluargaku?",
